using System; using System.Web.UI; using RecepcionDocumental.Data;
namespace RecepcionDocumental { public partial class Gmail_Mensaje_Ver : Page { protected void Page_Load(object sender, EventArgs e) { if (IsPostBack) return; long id; if (!long.TryParse(Request.QueryString["id"], out id) || id <= 0) { litAviso.Text="Indicá un identificador de mensaje válido."; return; } GmailMensajeInfo message; if (!GmailRepository.TryGetMensaje(id,out message)) { litAviso.Text="No se pudo consultar la base de datos."; return; } if(message==null){litAviso.Text="No se encontró el mensaje solicitado.";return;} pnlAviso.Visible=false;pnlMensaje.Visible=true;litAsunto.Text=Server.HtmlEncode(message.Asunto);litRemitente.Text=Server.HtmlEncode(message.Remitente);litCuenta.Text=Server.HtmlEncode(message.CuentaEmail);litFecha.Text=message.FechaMensajeUtc.ToString("dd/MM/yyyy HH:mm");litGmailId.Text=Server.HtmlEncode(message.GmailMessageId);litSnippet.Text=Server.HtmlEncode(message.Snippet??"Sin resumen disponible");var documents=DocumentRepository.ListByMessage(id);if(documents.Count>0){litItemsTitle.Text="Documentos procesados";pnlSinAdjuntos.Visible=false;pnlDocumentos.Visible=true;pnlAdjuntosHistoricos.Visible=false;rptDocumentos.DataSource=documents;rptDocumentos.DataBind();}else{var attachments=GmailSyncRepository.GetAttachments(id);litItemsTitle.Text="Adjuntos";pnlSinAdjuntos.Visible=attachments.Count==0;pnlDocumentos.Visible=false;pnlAdjuntosHistoricos.Visible=attachments.Count>0;rptAdjuntos.DataSource=attachments;rptAdjuntos.DataBind();} } protected string FormatSize(object value){if(value==null||value==DBNull.Value)return "—";var bytes=Convert.ToInt64(value);return bytes>=1048576?(bytes/1048576d).ToString("0.##")+" MB":bytes>=1024?(bytes/1024d).ToString("0.##")+" KB":bytes+" bytes";} protected string FormatConfidence(object value){return value==null||value==DBNull.Value?"—":Convert.ToByte(value).ToString()+"%";} } }
